from pysat.solvers import Glucose3
from pysat.card import *

n = 11
# Bipartition: A = {0, 1, 2, 3, 5, 6, 7}, B = {4, 8, 9, 10}
A = {0, 1, 2, 3, 5, 6, 7}
B = {4, 8, 9, 10}

# Create all possible edges between A and B
possible_edges = []
for u in A:
    for v in B:
        if u < v:
            possible_edges.append((u, v))
        else:
            possible_edges.append((v, u))

# Known edges that must be present
known_edges = [(1, 10), (0, 4), (0, 8), (2, 9)]

# Create variable mapping
edge_to_var = {}
var_to_edge = {}
for i, e in enumerate(possible_edges):
    edge_to_var[e] = i + 1
    var_to_edge[i + 1] = e

solver = Glucose3()

# Known edges must be present
for e in known_edges:
    # Normalize edge
    if e[0] > e[1]:
        e = (e[1], e[0])
    solver.add_clause([edge_to_var[e]])

# Each vertex needs degree >= 3
for v in range(n):
    # Find all possible edges incident to v
    incident_vars = []
    for e in possible_edges:
        if v in e:
            incident_vars.append(edge_to_var[e])

    # At least 3 of these must be true
    card = CardEnc.atleast(lits=incident_vars, bound=3, encoding=1)
    for clause in card.clauses:
        solver.add_clause(clause)

# Solve
if solver.solve():
    model = solver.get_model()
    edges = []
    for var in model:
        if var > 0:
            edges.append(var_to_edge[var])
    edges.sort()
    print(f"Solution found with {len(edges)} edges:")
    print(edges)

    # Verify
    degrees = [0] * n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}")

    # Check bipartite
    color = {}
    for u, v in edges:
        if u in color:
            if v in color:
                assert color[u] != color[v], f"Edge ({u},{v}) violates bipartite"
            else:
                color[v] = 1 - color[u]
        else:
            if v in color:
                color[u] = 1 - color[v]
            else:
                color[u] = 0
                color[v] = 1
    print("Bipartite check passed!")

    # Check max clique
    from itertools import combinations
    max_clique = 0
    for k in range(1, n+1):
        found = False
        for subset in combinations(range(n), k):
            # Check if all pairs are edges
            is_clique = True
            for i in range(k):
                for j in range(i+1, k):
                    u, v = subset[i], subset[j]
                    if u > v:
                        u, v = v, u
                    if (u, v) not in edges:
                        is_clique = False
                        break
                if not is_clique:
                    break
            if is_clique:
                found = True
                break
        if found:
            max_clique = k
        else:
            break
    print(f"Max clique size: {max_clique}")

    print("All constraints satisfied!")
else:
    print("No solution with this bipartition")
    solver.delete()

